(function(){
'use strict';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={disconnected:'Desconectado',connecting:'Conectando…',qr:'Esperando escaneo del QR',connected:'Conectado',logged_out:'Sesión cerrada',error:'Requiere atención'};
async function api(route,body){const r=await fetch('/api/zip/whatsapp/'+route,{credentials:'same-origin',cache:'no-store',...(body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)})});const d=await r.json();if(!r.ok)throw Object.assign(Error(d.error||'No se pudo completar la operación.'),{status:r.status});return d;}
function mount(root,management=false){
 let threads=[],users=[],selected=null,status={},running=false,sending=false,lastMessages='',request=null;
 root.classList.add('wa-root');root.innerHTML='<header class="wa-toolbar"><strong>WhatsApp CRM</strong><span class="wa-state" role="status">Consultando conexión…</span><button type="button" class="wa-refresh">Actualizar</button><span class="wa-manager-actions" hidden><button type="button" data-op="connect">Conectar / mostrar QR</button><button type="button" data-op="disconnect">Desconectar</button><button type="button" data-op="unlink">Restablecer vinculación</button></span></header><div class="wa-notice" role="status"></div><div class="wa-error" role="alert"></div><div class="wa-qr" hidden><img alt="QR para vincular WhatsApp"><p>En tu teléfono: WhatsApp → Dispositivos vinculados → Vincular un dispositivo. No compartas este QR.</p></div><div class="wa-layout"><aside class="wa-threads" aria-label="Conversaciones de WhatsApp"></aside><section class="wa-chat"><header class="wa-contact">Seleccioná una conversación</header><div class="wa-assign" hidden><label>Vendedor responsable <select aria-label="Vendedor responsable"></select></label><button type="button">Asignar y crear lead</button></div><div class="wa-messages" aria-label="Mensajes"></div><form class="wa-compose"><label>Mensaje<textarea aria-label="Mensaje de WhatsApp" rows="2" maxlength="4000" placeholder="Escribí una respuesta…"></textarea></label><button type="submit" disabled>Enviar a WhatsApp</button></form></section></div>';
 const q=s=>root.querySelector(s),err=e=>{q('.wa-error').textContent=e.message||String(e);if(e.status===401||e.status===403){q('.wa-threads').replaceChildren();q('.wa-messages').replaceChildren();q('.wa-qr').hidden=true;selected=null;status.phase='disconnected';q('[type=submit]').disabled=true;}};
 function drawThreads(){const list=q('.wa-threads');list.innerHTML=threads.length?'':'<p class="wa-empty">Todavía no hay conversaciones asignadas. Los mensajes nuevos aparecerán después de vincular WhatsApp.</p>';for(const t of threads){const b=document.createElement('button');b.type='button';b.className='wa-thread'+(selected===t.id?' active':'');b.innerHTML='<b>'+esc(t.name)+'</b><span>'+esc(t.phone)+'</span><small>'+esc(users.find(x=>x.id===t.ownerId)?.name||(t.ownerId?'Asignada':'Pendiente de asignación'))+'</small>';b.onclick=()=>{if(sending)return;selected=t.id;request=null;lastMessages='';q('textarea').value='';void refresh();};list.append(b);}}
 async function messages(){const t=threads.find(t=>t.id===selected);q('.wa-contact').textContent=t?t.name+' · '+t.phone:'Seleccioná una conversación';q('.wa-assign').hidden=!status.manager||!t;q('[type=submit]').disabled=sending||!t?.ownerId||status.phase!=='connected';if(!t){q('.wa-messages').replaceChildren();return;}
  if(status.manager){const select=q('.wa-assign select');select.innerHTML='<option value="">Elegí un vendedor</option>'+users.map(u=>'<option value="'+esc(u.id)+'" '+(u.id===t.ownerId?'selected':'')+'>'+esc(u.name||u.username)+'</option>').join('');}
  const data=await api('messages?thread='+encodeURIComponent(t.id));if(selected!==t.id)return;const signature=JSON.stringify(data.messages);if(signature===lastMessages)return;lastMessages=signature;
  const box=q('.wa-messages'),nearBottom=box.scrollHeight-box.scrollTop-box.clientHeight<100;box.replaceChildren();for(const m of data.messages){const b=document.createElement('div');b.className='wa-bubble '+m.direction;const text=document.createElement('p');text.textContent=m.text;const stamp=document.createElement('small');stamp.textContent=new Date(m.createdAt).toLocaleString('es-GT')+(m.direction==='out'?' · '+({sent:'Enviado a WhatsApp',pending:'Pendiente de confirmar',unknown:'Envío sin confirmar: revisá el teléfono antes de repetir'}[m.status]||m.status):'');b.append(text,stamp);box.append(b);}if(nearBottom||!box.scrollTop)box.scrollTop=box.scrollHeight;
 }
 async function refresh(){if(running||sending)return;running=true;try{status=await api('status');q('.wa-state').textContent=(labels[status.phase]||status.phase)+(status.number?' · '+status.number:'');q('.wa-notice').textContent=status.note||'';q('.wa-manager-actions').hidden=!management||!status.manager;
  if(status.manager&&management){users=(await api('users')).users;const qr=await api('qr');q('.wa-qr').hidden=!qr.image;if(qr.image)q('.wa-qr img').src=qr.image;else q('.wa-qr img').removeAttribute('src');}
  threads=(await api('threads')).threads;if(selected&&!threads.some(t=>t.id===selected)){selected=null;q('textarea').value='';}drawThreads();await messages();
 }catch(e){err(e);}finally{running=false;}}
 q('.wa-refresh').onclick=()=>{q('.wa-error').textContent='';void refresh();};
 root.querySelectorAll('[data-op]').forEach(b=>b.onclick=async()=>{if(b.dataset.op==='unlink'&&!confirm('¿Restablecer la vinculación? Se conservarán los mensajes del CRM y tendrás que escanear un QR nuevo.'))return;b.disabled=true;try{q('.wa-error').textContent='';await api(b.dataset.op,{});await refresh();}catch(e){err(e);}finally{b.disabled=false;}});
 q('.wa-assign button').onclick=async()=>{try{q('.wa-error').textContent='';await api('assign',{thread:selected,ownerId:q('.wa-assign select').value});await refresh();}catch(e){err(e);}};
 q('form').onsubmit=async e=>{e.preventDefault();const text=q('textarea').value.trim();if(!text||!selected||sending)return;if(!request||request.thread!==selected||request.text!==text)request={thread:selected,text,requestId:crypto.randomUUID()};sending=true;q('[type=submit]').disabled=true;q('.wa-error').textContent='';try{const r=await api('send',request);if(r.status==='sent'){q('textarea').value='';request=null;}else{q('.wa-error').textContent=r.message||'Envío pendiente de confirmar. Revisá el teléfono antes de repetirlo.';}}catch(e){err(e);}finally{sending=false;await refresh();}};
 void refresh();const timer=setInterval(()=>{if(document.visibilityState==='visible'&&root.getClientRects().length)void refresh();},5000);window.addEventListener('pagehide',()=>clearInterval(timer),{once:true});
}
function init(){
 const management=document.getElementById('whatsappAdmin');if(management){mount(management,true);return;}
 const inbox=document.getElementById('inbox');if(inbox){const old=[...inbox.children],bar=document.createElement('div'),wa=document.createElement('div');bar.className='wa-tabs';bar.innerHTML='<button type="button" aria-pressed="true">WhatsApp</button><button type="button" aria-pressed="false">Historial interno</button>';inbox.prepend(bar);inbox.append(wa);inbox.style.flexDirection='column';wa.style.flex='1';wa.style.minHeight='0';const toggle=live=>{old.forEach(el=>el.hidden=live);old.forEach(el=>el.style.display=live?'none':'');wa.hidden=!live;[...bar.children].forEach((b,i)=>b.setAttribute('aria-pressed',String(i===(live?0:1))));};bar.children[0].onclick=()=>toggle(true);bar.children[1].onclick=()=>toggle(false);toggle(true);mount(wa);}
 // Append an action to the existing portal without changing the other actions or their indices.
 if(typeof roleConfig!=='undefined'&&typeof runPortalAction==='function'){
  const indices={};for(const role of ['admin','gerencia']){indices[role]=roleConfig[role].actions.length;roleConfig[role].actions.push(['WhatsApp CRM','Vincular WhatsApp y asignar conversaciones a vendedores']);}
  if(typeof activeRole!=='undefined'&&activeRole==='admin'&&document.getElementById('portal')?.classList.contains('open')){const grid=document.getElementById('dashboardActions');if(grid){const b=document.createElement('button');b.type='button';b.className='dash-action';b.innerHTML='<b>WhatsApp CRM</b><small>Vincular WhatsApp y asignar conversaciones</small>';b.onclick=()=>window.runPortalAction('admin',indices.admin);grid.append(b);}}
  const old=window.runPortalAction;window.runPortalAction=function(role,index){if(index===indices[role]){openWorkspace('WhatsApp CRM','<iframe title="Administración de WhatsApp" src="/whatsapp-admin.html" style="border:0;width:100%;height:75dvh"></iframe>');return;}return old.apply(this,arguments);};
 }
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
})();
